changeSet.sql:
/****** Object: StoredProcedure [bulkload].[UpdateItemColumnByType] Script Date: 16/05/2019 12:22:17 ******/ SET ANSI_NULLS ON GO SET QUOTED_IDENTIFIER ON GO ALTER procedure [bulkload].[UpdateItemColumnByType] @id int, @ObjectType varchar(50), @ObjectTypeID int, @subjectAreaColumn int, @itemColumn int as begin set nocount on;
if @ObjectType = 'FusionAttributeType' begin update T set T.LookupObject = replace(@ObjectType, 'Type', ''), T.LookupObjectID = S.ID from LoadItemColumn T left join FusionAttribute S on lower(S.TextPath) = lower(T.Value) and S.FusionAttributeTypeID = @ObjectTypeID where T.LoadID = @id and T.ColumnIndex = @itemColumn end if @ObjectType = 'IntersectType' begin update T set T.LookupObject = replace(@ObjectType, 'Type', ''), T.LookupObjectID = S.ID from LoadItemColumn T left join [Intersect] S on S.IntersectTypeID = @ObjectTypeID where T.LoadID = @id and T.ColumnIndex = @itemColumn end
if @ObjectType = 'ReferenceItemType' and @ObjectTypeID = 0 begin update T set T.LookupObject = @ObjectType, T.LookupObjectID = S.ObjectID from LoadItemColumn T left join AssetType S on lower(S.Name) = lower(T.Value) and S.[Object] = 'ReferenceItemType' where T.LoadID = @id and T.ColumnIndex = @itemColumn end end

changeSet.rollback:
